// Mundo compartido: «Por qué se calientan las luces de Navidad viejas».
// Rincón de sala navideña de noche (maqueta): pared, ventana, alfombra, regalos, pino decorado
// con guirnalda y una mesita central donde cambia la fuente de luz.
// Qué se ve al EMPEZAR cada paso:
//  0: sala, árbol con la guirnalda encendida, mesita vacía.
//  1: igual + la chispa junto a la guirnalda + la mano retirada (se quemó).
//  2: igual + nube de "más potencia" tachada con X roja sobre la guirnalda.
//  3: guirnalda apagada; fogata pequeña sobre la mesita con la chispa.
//  4: vela blanca encendida con la chispa en la llama.
//  5: foco clásico colgando con filamento incandescente; chispa en el alambre.
//  6: foco + ondas rojas de calor enormes + rayito de luz + barra al 90 %.
//  7: foco + monedas de energía escapando hacia arriba + rayito + barra.
//  8: tubo fluorescente blanco con pocas ondas.
//  9: foco LED con chip en corte, casi sin ondas.
// 10: foco viejo a la izquierda (muchas ondas) y LED a la derecha (muy pocas).
// 11+: los cinco tipos de luz alineados en un banco bajo el árbol, guirnalda encendida y la mano tocando el LED.
import React from 'react';
import * as THREE from 'three';
import {Pieza, Linea, Cartel, Ojos, ConoDeLuz, flotar} from '../lib3d';
import type {Paleta, V3} from '../lib3d';

export const PARTES = [
  'sala', 'arbol', 'guirnalda', 'mesita', 'chispa', 'mano', 'nube', 'fogata', 'vela',
  'foco', 'rayo', 'ondas', 'barra', 'monedas', 'tubo', 'led', 'fila',
] as const;

export type ParteProps = {paleta: Paleta; resaltado?: boolean; frame?: number};
export type MundoProps = {paso: number; frame: number; fps: number; paleta: Paleta; ocultar?: string[]; resaltar?: string[]};

// ---------- Medidas y sitios fijos ----------
export const ARBOL: V3 = [0, 0, -0.55];
export const SITIO: V3 = [0, 0.425, 0.32]; // tablero de la mesita
export const COLGADO: V3 = [0, 0.86, 0.32]; // centro del foco que cuelga
export const MANO_FIN: V3 = [0.92, 0.25, 0.84]; // tocando el LED de la fila
export const MANO_ANTES: V3 = [1.02, 1.0, 0.42]; // retirada de la guirnalda
const AMARILLO = '#FFD23A';
const MADERA = '#8A5532';
const METAL = '#BDB6A8';

export const guirnaldaEncendida = (paso: number) => paso <= 2 || paso >= 11;
export const llenadoBarra = (paso: number) => (paso >= 6 && paso <= 7 ? 0.9 : 0);
export const posChispa = (paso: number): V3 => {
  if (paso <= 2) return [0.4, 1.05, 0.2];
  if (paso === 3) return [0, 0.66, 0.44];
  if (paso === 4) return [0.0, 0.76, 0.38];
  if (paso <= 7) return [0, 0.85, 0.44];
  if (paso === 8) return [0.2, 0.79, 0.38];
  if (paso === 9) return [0, 0.84, 0.42];
  if (paso === 10) return [0.42, 0.84, 0.42];
  return [0.58, 0.46, 0.86];
};
export const escalaChispa = (paso: number) => (paso >= 3 && paso <= 10 ? 0.65 : 1);

// Capas del pino: [base, punta, radio]
const CAPAS: [number, number, number][] = [[0.2, 0.9, 0.62], [0.65, 1.25, 0.5], [1.08, 1.58, 0.36], [1.45, 1.82, 0.22]];
const radioArbol = (y: number) =>
  Math.max(0, ...CAPAS.map(([b, t, r]) => (y >= b && y <= t ? (r * (t - y)) / (t - b) : 0)));
const enArbol = (y: number, a: number, extra = 0.01): V3 => {
  const r = radioArbol(y) * 0.95 + extra;
  return [ARBOL[0] + Math.sin(a) * r, y, ARBOL[2] + Math.cos(a) * r];
};

// ---------- Geometrías curvas (onda de calor y filamento en espiral) ----------
const curvas = new Map<string, THREE.TubeGeometry>();
const tuboCurvo = (clave: string, pts: V3[], r: number, seg = 64) => {
  let g = curvas.get(clave);
  if (!g) {
    g = new THREE.TubeGeometry(new THREE.CatmullRomCurve3(pts.map((q) => new THREE.Vector3(...q))), seg, r, 6, false);
    curvas.set(clave, g);
  }
  return g;
};
const ONDA = Array.from({length: 11}, (_, i): V3 => [Math.sin(i * 1.1) * 0.035, i * 0.04, 0]);
const ESPIRAL = Array.from({length: 73}, (_, i): V3 => {
  const t = i / 72;
  return [-0.05 + t * 0.1, Math.sin(t * Math.PI * 14) * 0.016, Math.cos(t * Math.PI * 14) * 0.016];
});

// ---------- Fuentes de luz en coordenadas locales (se reutilizan en la fila final) ----------
type Local = {paleta: Paleta; resaltado?: boolean; frame?: number; luz?: boolean};

const FogataLocal: React.FC<Local> = ({paleta, resaltado, frame = 0, luz = true}) => {
  const llama = resaltado ? paleta.acentos[2] : '#F07A22';
  const v = 1 + Math.sin(frame * 0.45) * 0.08 + Math.sin(frame * 0.9) * 0.04;
  return (
    <group>
      {Array.from({length: 7}, (_, i) => {
        const a = (i / 7) * Math.PI * 2;
        return <Pieza key={i} forma="esfera" medidas={[0.04]} color="#8C8880" posicion={[Math.cos(a) * 0.16, 0.03, Math.sin(a) * 0.16]} escala={[1, 0.75, 1]} />;
      })}
      {[0, 1.05, 2.1].map((a, i) => (
        <Pieza key={`t${i}`} forma="cilindro" medidas={[0.028, 0.032, 0.3]} color={i % 2 ? '#7A4A2A' : '#8E5A33'} posicion={[0, 0.07, 0]} rotacion={[0, a, Math.PI / 2 - 0.22]} />
      ))}
      <group scale={[1, v, 1]}>
        <Pieza forma="cono" medidas={[0.1, 0.26]} color={llama} brillo={llama} posicion={[0, 0.2, 0]} />
        <Pieza forma="cono" medidas={[0.045, 0.13]} color="#E4532A" brillo="#E4532A" posicion={[0.07, 0.14, 0.02]} />
        <Pieza forma="cono" medidas={[0.045, 0.12]} color="#E4532A" brillo="#E4532A" posicion={[-0.07, 0.14, 0.03]} />
        <Pieza forma="cono" medidas={[0.055, 0.16]} color={AMARILLO} brillo={AMARILLO} posicion={[0, 0.16, 0.05]} contorno={false} />
      </group>
      {luz ? <pointLight color="#FFA040" intensity={2.2} distance={3} decay={2} position={[0, 0.3, 0.1]} /> : null}
    </group>
  );
};

