      <Pieza forma="esfera" medidas={[0.018]} color="#F4F0E6" posicion={[0.045, 0.24, 0.01]} escala={[1, 1.8, 1]} />
      <Pieza forma="cilindro" medidas={[0.004, 0.004, 0.03]} color="#2A2420" posicion={[0, 0.28, 0]} contorno={false} />
      <Pieza forma="esfera" medidas={[0.026]} color="#FFB52E" brillo="#FFB52E" posicion={[0, 0.318, 0]} escala={[1, 1.9 * v, 1]} />
      <Pieza forma="esfera" medidas={[0.012]} color="#FFF6D0" brillo="#FFF6D0" posicion={[0, 0.306, 0.01]} contorno={false} />
