export const Arbol: React.FC<ParteProps> = ({paleta, resaltado, frame = 0}) => {
  const verde = resaltado ? paleta.acentos[2] : '#2F7A45';
  const bolas: [number, number, string][] = [[0.42, -0.6, '#D2452F'], [0.52, 0.55, '#E0A526'], [0.78, -0.2, '#E0A526'], [0.96, 0.7, '#D2452F'], [1.14, -0.5, '#3D8CE8'], [1.3, 0.35, '#E0A526'], [1.52, -0.1, '#D2452F'], [0.7, 1.1, '#3D8CE8'], [0.6, -1.2, '#E0A526']];
  return (
    <group>
      <group position={ARBOL}>
        <Pieza forma="cilindro" medidas={[0.17, 0.13, 0.16]} color="#B8322A" posicion={[0, 0.08, 0]} />
        <Pieza forma="cilindro" medidas={[0.06, 0.07, 0.2]} color="#6B4226" posicion={[0, 0.2, 0]} />
        {CAPAS.map(([b, t, r], i) => (
          <Pieza key={i} forma="cono" medidas={[r, t - b]} color={i % 2 ? '#2A6E3F' : verde} posicion={[0, (b + t) / 2, 0]} rotacion={[0, i * 0.4, 0]} />
        ))}
        <Pieza forma="esfera" medidas={[0.06]} color={AMARILLO} brillo="#FFC21A" posicion={[0, 1.85, 0]} escala={1 + flotar(frame, 0.06, 40)} />
      </group>
      {bolas.map(([y, a, c], i) => <Pieza key={i} forma="esfera" medidas={[0.035]} color={c} posicion={enArbol(y, a, 0.025)} />)}
    </group>
  );
};

export const Guirnalda: React.FC<ParteProps & {encendida?: boolean}> = ({paleta, resaltado, frame = 0, encendida = true}) => {
  const colores = ['#E8402F', '#F5C32C', '#3FBF5A', '#3D8CE8'];
  const pts = Array.from({length: 26}, (_, i) => {
    const t = i / 25;
    const y = 0.32 + t * 1.33;
    return enArbol(y, t * Math.PI * 7 - 1.6, 0.02);
  });
  return (
    <group>
      {pts.slice(1).map((p, i) => <Linea key={`c${i}`} desde={pts[i]} hasta={p} grosor={0.004} color="#1F3A26" />)}
      {pts.map((p, i) => {
        const c = resaltado ? paleta.acentos[2] : colores[i % 4];
        return (
          <mesh key={i} position={p}>
            <capsuleGeometry args={[0.018, 0.03, 4, 8]} />
            {encendida ? <meshBasicMaterial color={c} toneMapped={false} opacity={0.85 + 0.15 * Math.sin(frame * 0.2 + i)} transparent /> : <meshToonMaterial color="#5A5550" />}
          </mesh>
        );
      })}
      {encendida ? <pointLight color="#FFC27A" intensity={1.5} distance={2.5} decay={2} position={[0, 1.0, -0.05]} /> : null}
    </group>
  );
};

