/** Ondas rojas de calor que suben desde un punto; cantidad y tamaño marcan cuánto se pierde. */
export const OndasCalor: React.FC<{posicion: V3; cantidad: number; tam?: number; frame?: number; color: string}> = ({posicion, cantidad, tam = 1, frame = 0, color}) => {
  const g = tuboCurvo('onda', ONDA, 0.013);
  return (
    <group position={posicion}>
      {Array.from({length: cantidad}, (_, i) => {
        const ph = ((frame + i * 23) % 54) / 54;
        const ang = (i / Math.max(1, cantidad - 1) - 0.5) * 2.4;
        const r = 0.13 * tam + ph * 0.12 * tam;
        return (
          <group key={i} position={[Math.sin(ang) * r, 0.05 + ph * 0.35 * tam, Math.cos(ang) * 0.06]} rotation={[0, 0, -ang * 0.4]} scale={tam * (0.7 + 0.4 * ph)}>
            <mesh geometry={g}>
              <meshBasicMaterial color={color} toneMapped={false} transparent opacity={Math.sin(ph * Math.PI) * 0.95} depthWrite={false} />
            </mesh>
          </group>
        );
      })}
    </group>
  );
};

