export const Barra: React.FC<ParteProps & {llenado?: number}> = ({paleta, resaltado, llenado = 0.9}) => {
  const H = 0.8;
  const rojo = resaltado ? paleta.acentos[2] : paleta.acentos[0];
  return (
    <group position={[0.9, 0.72, 0.12]}>
      <Pieza forma="caja" medidas={[0.16, H + 0.05, 0.05]} color="#F7F4EE" posicion={[0, H / 2, 0]} />
      {llenado > 0.001 ? <Pieza forma="caja" medidas={[0.11, H * llenado, 0.02]} color={rojo} posicion={[0, (H * llenado) / 2, 0.03]} /> : null}
      {llenado < 0.999 ? <Pieza forma="caja" medidas={[0.11, H * (1 - llenado), 0.02]} color={AMARILLO} posicion={[0, H * llenado + (H * (1 - llenado)) / 2, 0.03]} /> : null}
      <Cartel texto={`${Math.round(llenado * 100)}%`} posicion={[0, H + 0.15, 0.05]} alto={0.14} fondo="transparent" colorTexto="#FFFFFF" borde="#1B1B1F" />
    </group>
  );
};

