// ---------- El mundo según el paso ----------
export const Mundo: React.FC<MundoProps> = ({paso, frame, paleta, ocultar = [], resaltar = []}) => {
  const ver = (n: string) => !ocultar.includes(n);
  const pp = (n: string) => ({paleta, frame, resaltado: resaltar.includes(n)});
  const xFoco = paso === 10 ? -0.42 : 0;
  const xLed = paso === 10 ? 0.42 : 0;
  return (
    <group>
      {ver('sala') ? <Sala {...pp('sala')} /> : null}
      {ver('arbol') ? <Arbol {...pp('arbol')} /> : null}
      {ver('guirnalda') ? <Guirnalda {...pp('guirnalda')} encendida={guirnaldaEncendida(paso)} /> : null}
      {ver('mesita') ? <Mesita {...pp('mesita')} /> : null}
      {paso === 1 && ver('mano') ? <Mano {...pp('mano')} posicion={MANO_ANTES} /> : null}
      {paso >= 11 && ver('mano') ? <Mano {...pp('mano')} /> : null}
      {paso === 2 && ver('nube') ? <Nube {...pp('nube')} /> : null}
      {paso === 3 && ver('fogata') ? <Fogata {...pp('fogata')} /> : null}
      {paso === 4 && ver('vela') ? <Vela {...pp('vela')} /> : null}
      {paso >= 5 && paso <= 10 && ver('foco') ? <group position={[xFoco, 0, 0]}><Foco {...pp('foco')} /></group> : null}
      {(paso === 6 || paso === 7) && ver('rayo') ? <Rayo {...pp('rayo')} /> : null}
      {(paso === 6 || paso === 10) && ver('ondas') ? <Ondas {...pp('ondas')} posicion={[xFoco, COLGADO[1], COLGADO[2]]} cantidad={10} tam={1.4} /> : null}
      {paso === 8 && ver('ondas') ? <Ondas {...pp('ondas')} posicion={[0, 0.8, SITIO[2]]} cantidad={4} tam={0.9} /> : null}
      {(paso === 9 || paso === 10) && ver('ondas') ? <Ondas {...pp('ondas')} posicion={[xLed, COLGADO[1], COLGADO[2]]} cantidad={2} tam={0.55} /> : null}
      {(paso === 6 || paso === 7) && ver('barra') ? <Barra {...pp('barra')} llenado={llenadoBarra(paso)} /> : null}
      {paso === 7 && ver('monedas') ? <Monedas {...pp('monedas')} /> : null}
      {paso === 8 && ver('tubo') ? <Tubo {...pp('tubo')} /> : null}
      {(paso === 9 || paso === 10) && ver('led') ? <group position={[xLed, 0, 0]}><Led {...pp('led')} /></group> : null}
      {paso >= 11 && ver('fila') ? <Fila {...pp('fila')} /> : null}
      {paso >= 1 && ver('chispa') ? <Chispa {...pp('chispa')} posicion={posChispa(paso)} escala={escalaChispa(paso)} /> : null}
    </group>
  );
};
